// lib/og-fonts.ts
//
// GENERATED — base64-embedded Urbanist TTFs for the OG card renderer.
// Source files: assets/fonts/Urbanist-Black.ttf, assets/fonts/Urbanist-SemiBold.ttf
// (Urbanist, SIL Open Font License, via Google Fonts.)
// Embedded because Satori needs raw font data and neither fs nor bundler
// asset URLs are available across all runtimes (Turbopack dev/build +
// Cloudflare workers). If the TTFs change, regenerate the base64 constants:
//
//   node -e "const fs=require('fs');const b=fs.readFileSync('assets/fonts/Urbanist-Black.ttf').toString('base64');const s=fs.readFileSync('assets/fonts/Urbanist-SemiBold.ttf').toString('base64');const cur=fs.readFileSync('lib/og-fonts.ts','utf8');fs.writeFileSync('lib/og-fonts.ts',cur.replace(/URBANIST_BLACK_B64 = '[^']*'/,\`URBANIST_BLACK_B64 = '\${b}'\`).replace(/URBANIST_SEMIBOLD_B64 = '[^']*'/,\`URBANIST_SEMIBOLD_B64 = '\${s}'\`))"

function decode(b64: string): ArrayBuffer {
  if (typeof Buffer !== 'undefined') {
    const buf = Buffer.from(b64, 'base64');
    return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer;
  }
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

const URBANIST_BLACK_B64 = '';
const URBANIST_SEMIBOLD_B64 = '';

export const urbanistBlack = (): ArrayBuffer => decode(URBANIST_BLACK_B64);
export const urbanistSemiBold = (): ArrayBuffer => decode(URBANIST_SEMIBOLD_B64);
